import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

/**
 * Point `next-env.d.ts` back at the tree that actually gets typechecked.
 *
 * Next rewrites that file on every start, to reference the route types in
 * whichever build directory it is using -- and this run uses `.next-e2e`, so
 * that two dev servers do not share one build. The file it writes outlives
 * the run: it is a triple-slash reference, which is resolved *before*
 * `exclude` is consulted, so afterwards `tsc` typechecks the project against
 * route types generated by a test run.
 *
 * That is not theoretical. It broke the typecheck the moment a nested layout
 * was added: the e2e tree still said the only layout was `/`, the real one
 * said `/` and `/dashboard`, and the two global declarations of `LayoutProps`
 * disagreed -- with `skipLibCheck` hiding the duplicate that would have
 * explained it.
 *
 * Rewritten rather than deleted, because a missing `next-env.d.ts` is a
 * typecheck that cannot resolve `next` at all until somebody starts a build.
 */
export default function globalTeardown(): void {
  const file = path.resolve(__dirname, "..", "next-env.d.ts");
  if (!existsSync(file)) return;

  const before = readFileSync(file, "utf8");
  const after = before.replace(/\.\/\.next-e2e\//g, "./.next/");
  if (after !== before) writeFileSync(file, after);
}
